{
  "editions": [
    {
      "edition": "standard",
      "verdict": "revise",
      "checks": {
        "complete_coverage": false,
        "no_added_claims": false,
        "names_and_negations": true,
        "speaker_attribution": true,
        "source_choices_and_notes": true,
        "terminology_policy": true
      },
      "findings": [
        {
          "source_quote": "θέλει τὴν κλῆσιν τὴν γενομένην διὰ τοῦ υἱοῦ αὐτοῦ σώζεσθαι.",
          "english_quote": "wants those called through his Son to be saved.",
          "issue": "The grammatical object of the desire for preservation or salvation is the calling that came through the Son, not explicitly the people called. The note acknowledges the substitution, but the main text replaces this difficult assertion with an interpretation of its implied beneficiaries.",
          "suggested_revision": "Consider: “wants the calling that came through his Son to be saved.” Preserve “those called” as an interpretive alternative in the note rather than treating it as equivalent to the explicit source wording. The replacement requires fresh review.",
          "severity": "major"
        },
        {
          "source_quote": "ἀλλὰ μακρόθυμος ὢν ὁ Κύριος θέλει τὴν κλῆσιν τὴν γενομένην διὰ τοῦ υἱοῦ αὐτοῦ σώζεσθαι.",
          "english_quote": "Retain both invited groups, the response conditions, suffering without supplied willingness, and the explicit Spirit/Son statement.",
          "issue": "This unit's theological metadata claims to retain suffering and an explicit Spirit/Son statement, neither of which occurs in the selected section. The reference to both invited groups likewise imports a decision from another section. This misstates the source basis of this record.",
          "suggested_revision": "Replace the copied cross-section decision with unit-specific metadata covering the universal repentance offer, unworthiness because of deeds, the calling through the Son, and the stated response conditions. If these are collection-level decisions, label them as such rather than claiming they are retained in this unit.",
          "severity": "minor"
        }
      ]
    },
    {
      "edition": "simplified",
      "verdict": "revise",
      "checks": {
        "complete_coverage": false,
        "no_added_claims": false,
        "names_and_negations": true,
        "speaker_attribution": true,
        "source_choices_and_notes": true,
        "terminology_policy": true
      },
      "findings": [
        {
          "source_quote": "θέλει τὴν κλῆσιν τὴν γενομένην διὰ τοῦ υἱοῦ αὐτοῦ σώζεσθαι.",
          "english_quote": "He wants those called through his Son to be saved.",
          "issue": "The simplified edition independently replaces the explicit object, the calling that came through the Son, with the people inferred from that calling. Disclosure in the note does not preserve the source assertion in the reader text.",
          "suggested_revision": "Consider: “He wants the calling that came through his Son to be saved.” Explain the possible reference to the people called in the note. Review any replacement afresh.",
          "severity": "major"
        },
        {
          "source_quote": "λήψονται ἴασιν παρὰ τοῦ Κυρίου τῶν προτέρων ἁμαρτιῶν, ἐὰν μὴ διψυχήσωσιν ἐπὶ ταῖς ἐντολαῖς ταύταις, καὶ ζήσονται τῷ Θεῷ.",
          "english_quote": "will receive healing from the Lord for their former sins. They must not waver over these commandments. They will live to God.",
          "issue": "The source makes not wavering an explicit condition of the promised healing. Splitting it into a separate obligation removes the grammatical condition and presents healing as assured before that requirement is stated. The note's claim that the conditions remain explicit does not repair this change in the main text.",
          "suggested_revision": "Keep the condition attached to the promise, for example: “will receive healing from the Lord for their former sins if they do not waver over these commandments. They will live to God.” Review the revised sentence against the entire conditional construction.",
          "severity": "major"
        },
        {
          "source_quote": "πείθομαι γὰρ ὅτι εἷς ἕκαστος τὰ ἴδια ἔργα ἐπιγνοὺς καὶ φοβηθεὶς τὸν Θεὸν μετανοήσει.",
          "english_quote": "I am convinced that each person will recognize their own deeds, fear God and repent.",
          "issue": "The source predicts repentance upon recognition of one's deeds and fear of God. The simplified coordination instead explicitly predicts all three actions for each person, extending the scope of the speaker's assurance.",
          "suggested_revision": "Consider: “I am convinced that each person, once they recognize their own deeds and fear God, will repent.” Preserve the relationship between the participles and the predicted repentance; review the replacement afresh.",
          "severity": "major"
        },
        {
          "source_quote": "ἀλλὰ μακρόθυμος ὢν ὁ Κύριος θέλει τὴν κλῆσιν τὴν γενομένην διὰ τοῦ υἱοῦ αὐτοῦ σώζεσθαι.",
          "english_quote": "Retain both invited groups, the response conditions, suffering without supplied willingness, and the explicit Spirit/Son statement.",
          "issue": "The theological decision attributes material from other sections to this unit: suffering and an explicit Spirit/Son identification are absent here, and the two-group decision belongs elsewhere.",
          "suggested_revision": "Write a unit-specific theological decision, or explicitly identify this as collection-level metadata that does not describe the contents of this section.",
          "severity": "minor"
        },
        {
          "source_quote": "Καὶ μετὰ τὸ συντελέσαι αὐτὸν τὰς ἐπιλύσεις πασῶν τῶν ῥάβδων λέγει μοι·",
          "english_quote": "Retain rod fractions, both invited groups, repentance conditions, suffering without supplied willingness, the Spirit/Son identification and all twelve distinct mountain descriptions; preserve substantive alternative notes.",
          "issue": "The simplification metadata claims preservation of rod fractions, suffering, Spirit/Son identification, and twelve mountain descriptions that are not present in this selected section. It therefore does not accurately document this edition's simplification decisions.",
          "suggested_revision": "Replace this with section-specific documentation of sentence splitting, repentance terminology, the calling construction, and preservation of conditional promises and warnings.",
          "severity": "minor"
        }
      ]
    }
  ],
  "summary": "Both editions require revision. The standard substitutes people for the source's explicit calling; the simplified edition also detaches a condition from the healing promise and expands the assurance in paragraph 2. Both contain cross-section metadata presented as unit-specific decisions. The disclosed possessive working reading and bracketed supplements need not be replaced: their principal textual distinctions are honestly reported in relation to the supplied project evidence. This review does not authenticate unseen manuscripts or certify an exhaustive collation."
}
